//           │                               └─► W  write token ─► R = HMAC(W, "outheis-agenda/read")
//           └─► D   delete token
//   F       = first 11 bytes of SHA-256(D)  (fingerprint, not secret)
//   account = SHA-256( F ‖ SHA-256(R) )
